package deploy

import (
	"context"
	"math/big"
	"testing"
	"time"

	"github.com/ninja-protocol-labs/go-evmkit/core/abi"
	"github.com/ninja-protocol-labs/go-lib-cryptography/encoding"
	"github.com/stretchr/testify/suite"

	"github.com/ninja-protocol-labs/go-evmkit/core"
	"github.com/ninja-protocol-labs/go-evmkit/core/types"
	"github.com/ninja-protocol-labs/go-evmkit/rpc"
	"github.com/ninja-protocol-labs/go-evmkit/tx"
)

// erc20ByteCodeHex is OpenZeppelin's ERC20 plus mint/burn, constructor(name, symbol, decimals).
const erc20ByteCodeHex = ""

type CreateDeployerSuite struct {
	suite.Suite

	Enable        bool
	RPCURL        string
	PrivateKeyHex string
	ByteCode      string
	Constructor   *abi.Function
	Args          []any

	ctx    context.Context
	cancel context.CancelFunc

	client rpc.Client

	signer core.Signer
	from   *types.Address

	deployment *ContractDeployment
	deployer   *CreateDeployer
}

func TestERC20CreateDeployerSuite(t *testing.T) {
	suite.Run(t, &CreateDeployerSuite{
		Enable:        false,
		RPCURL:        "https://api.avax-test.network/ext/bc/C/rpc",
		PrivateKeyHex: "",
		ByteCode:      erc20ByteCodeHex,
		Constructor:   abi.NewFunction("constructor", abi.Types{abi.String, abi.String, abi.Uint8}, nil),
		Args:          []any{"evmkit test ERC20", "EVK20", uint8(18)},
	})
}

func (s *CreateDeployerSuite) SetupSuite() {
	if !s.Enable {
		s.T().Skip("disabled")
	}

	s.ctx, s.cancel = context.WithTimeout(context.Background(), 60*time.Second)

	s.client = rpc.NewClient(s.RPCURL)

	privKey, err := types.NewPrivateKeyFromHex(s.PrivateKeyHex)
	s.Require().NoError(err)
	s.signer = privKey
	s.from = core.PubkeyToAddress(privKey.PublicKey())

	bytecode, err := encoding.Hex.Decode(s.ByteCode)
	s.Require().NoError(err)

	s.deployment = NewContractDeployment(bytecode, s.Constructor.Inputs, s.Args)

	s.deployer = NewCreateDeployer(s.client)
}

func (s *CreateDeployerSuite) TearDownSuite() {
	if s.cancel != nil {
		s.cancel()
	}
}

func (s *CreateDeployerSuite) TestDeploy() {
	unsigned, err := s.deployer.CreateDeployment(s.ctx, tx.NewLegacyBuilder(), s.from, big.NewInt(0), s.deployment)
	s.Require().NoError(err)

	predicted, err := s.deployer.DeployAddress(s.from, unsigned.AddressNonce())
	s.Require().NoError(err)

	s.Require().NoError(unsigned.Sign(s.signer))

	hash, err := s.deployer.Deploy(s.ctx, unsigned)
	s.Require().NoError(err)

	receipt, err := tx.WaitForReceipt(s.ctx, s.client, hash, 0, 0)
	s.Require().NoError(err)
	s.Require().True(receipt.Status, "transaction reverted")
	s.Require().NotNil(receipt.ContractAddress)
	s.Require().True(receipt.ContractAddress.Equal(predicted))

	s.T().Logf("TestDeploy Result")
	s.T().Logf("\tAddress: %s", receipt.ContractAddress)
	s.T().Logf("\tTx: %s", hash)
	s.T().Logf("\tTxType: 0x%v", unsigned.Type())
	s.T().Logf("\tGas: %d", unsigned.Gas())
	s.T().Logf("\tNonce: %d", unsigned.AddressNonce())
	s.T().Logf("\tMaxFee: %s", unsigned.MaxFee())
}
